/**
 * The main Worker's entry (wrangler.jsonc `main`): the OpenNext app as built
 * by `opennextjs-cloudflare build`, plus one RPC entrypoint.
 *
 * `DebugSessions` is reachable only over a service binding (lianki-push's
 * `SESSIONS`, entrypoint "DebugSessions"), never from the internet — an RPC
 * entrypoint has no URL. lianki-push's debug hub asks it whether the owner's
 * session is still live right before renewing an eval grant
 * (lib/debug-session.ts; docs/monitoring.md, "Renewal").
 */
import { WorkerEntrypoint } from "cloudflare:workers";
// @ts-ignore -- generated by `opennextjs-cloudflare build`, absent before it
import { default as handler } from "./.open-next/worker.js";
import { rateLimiter, sessionLive, type SessionDb } from "./lib/debug-session";

export default { fetch: handler.fetch };

type Env = { DB?: SessionDb; OWNER_EMAILS?: string };

/** At most 60 checks a minute per isolate, whoever asks. */
const allow = rateLimiter(60, 60_000);

export class DebugSessions extends WorkerEntrypoint<Env> {
  /**
   * "live" only for the owner's unexpired session with this tag; "gone" for
   * anything else; "busy" over the rate limit (the hub renews nothing then,
   * and keeps the chain). A D1 error throws: the hub treats it as unsure.
   */
  async live(user: unknown, tag: unknown): Promise<"live" | "gone" | "busy"> {
    if (!allow()) return "busy";
    const ok = await sessionLive(this.env.DB, user, tag, { ownerEmails: this.env.OWNER_EMAILS });
    return ok ? "live" : "gone";
  }
}
